// OrdersDashboard.js

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import '../../CSS/OrdersDashboard.css'; // Add your custom CSS for styling
import { Link } from 'react-router-dom';

const OrdersDashboard = () => {
  const [currentPage, setCurrentPage] = useState(1);
  const ordersPerPage = 20;

  const navigate = useNavigate(); // Initializes navigate

  // Sample orders data
  const orders = new Array(50).fill(null).map((_, index) => ({
    id: `#ISH10${index + 1}`,
    date: `2 Apr at 7:${index % 60} pm`,
    customer: `Customer ${index + 1}`,
    channel: 'Online Store',
    total: `₹${(Math.random() * 50000 + 2000).toFixed(2)}`,
    paymentStatus: index % 3 === 0 ? 'Pending' : 'Paid',
    fulfillmentStatus: index % 2 === 0 ? 'Fulfilled' : 'Unfulfilled',
    items: `${Math.floor(Math.random() * 4) + 1} items`,
    deliveryStatus: 'Tracking added',
    deliveryMethod: 'Standard',
  }));

  const indexOfLastOrder = currentPage * ordersPerPage;
  const indexOfFirstOrder = indexOfLastOrder - ordersPerPage;
  const currentOrders = orders.slice(indexOfFirstOrder, indexOfLastOrder);

  // Navigate to the order details page on click
  const handleOrderClick = (orderId) => {
    navigate(`/order/${orderId}`); // This will navigate to the order details page
  };

  return (
    <div className="dashboard-container">
      <div className="dashboard-header">
        <h2>Orders</h2>
        <div className="dashboard-actions">
          <button className="btn export">Export</button>
          <button className="btn primary">Create Order</button>
        </div>
      </div>

      <div className="order-summary">
        {['Orders', 'Items ordered', 'Returns', 'Orders fulfilled', 'Orders delivered', 'Order to fulfill'].map((label) => (
          <div className="summary-box" key={label}>
            <p className="label">{label}</p>
            <p className="value">0</p>
          </div>
        ))}
      </div>

      <div className="tabs">
        {['All', 'Unfulfilled', 'Unpaid', 'Open', 'Archived', 'Return requests'].map(tab => (
          <button key={tab} className="tab">{tab}</button>
        ))}
      </div>

      <div className="order-table">
        <table>
          <thead>
            <tr>
              <th><input type="checkbox" /></th>
              <th>Order</th>
              <th>Date</th>
              <th>Customer</th>
              <th>Channel</th>
              <th>Total</th>
              <th>Payment status</th>
              <th>Fulfillment status</th>
              <th>Items</th>
              <th>Delivery status</th>
              <th>Delivery method</th>
            </tr>
          </thead>
          <tbody>
            {currentOrders.map((order, idx) => (
              <tr key={idx} onClick={() => handleOrderClick(order.id)}>
                <td><input type="checkbox" /></td>
                <td>{order.id}</td>
                <td>{order.date}</td>
                <td>{order.customer}</td>
                <td>{order.channel}</td>
                <td>{order.total}</td>
                <td>
                  <span className={`badge ${order.paymentStatus.toLowerCase()}`}>
                    {order.paymentStatus}
                  </span>
                </td>
                <td>
                  <span className={`badge ${order.fulfillmentStatus.toLowerCase()}`}>
                    {order.fulfillmentStatus}
                  </span>
                </td>
                <td>{order.items}</td>
                <td>{order.deliveryStatus}</td>
                <td>{order.deliveryMethod}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="pagination">
        <button disabled={currentPage === 1} onClick={() => setCurrentPage(prev => prev - 1)}>Previous</button>
        <span>Page {currentPage}</span>
        <button disabled={indexOfLastOrder >= orders.length} onClick={() => setCurrentPage(prev => prev + 1)}>Next</button>
      </div>
    </div>
  );
};

export default OrdersDashboard;
